    /** Usages for any of [keys] (combined-row cards represent >1 key). */
    fun forKeys(keys: List<String>): List<Usage> =
        keys.flatMap { USAGES[it] ?: emptyList() }
            .distinct()
            .sortedWith(compareBy({ it.screen.lowercase() }, { it.location }))
}
